// Prose lives here; the markup around it lives in components/WhatsNew.astro.
// `{VERSION}` in a CTA label is replaced at render time.
import type { WhatsNewData } from './types';

const data: WhatsNewData = {
  version: "4.12.1",
  meta: {
    title: "Neu in SoloMD {VERSION} — Versionshinweise v4.0 – v4.11",
    description: "Versionshinweise zu SoloMD {VERSION}. v4.11: fehlerhafte Tabellen aus KI-/PDF-Exporten reparieren und rendern sich jetzt von selbst, dazu optional nummerierte Abschnittsüberschriften (6.2 → h2) in App, CLI und MCP. v4.8: Bild-Hosting (PicGo / SM.MS / S3 / GitHub) plus Verbesserungen im Alltag (Alles auswählen, Löschen in den Papierkorb, einheitliche Zeilenumbrüche). v4.7: Windows-Editor auf nativen Textareas neu gebaut — CJK-IME endlich zuverlässig. v4.6: Wissensgraph (typisierte Beziehungen, gespeicherte Ansichten, Eigenschaften-Inspektor) + tldraw-Whiteboards. v4.0: die agent-native Author-Version — Inline-Agent-Panel, geplante Recipes, Trace-Ansicht, MCP-Föderation.",
  },
  breadcrumb: {
    home: "Startseite",
    current: "Updates",
  },
  hero: {
    date: "Mai 2026",
    h1: "Der Editor, in dem Agents leben.",
    lead: "v4.0 ist die <strong>agent-native author</strong> Major-Release. Agents sind\n        von \"externes CLI gelegentlich aufrufen\" zu erstklassigen Bürgern im\n        Editor geworden — kontinuierlich präsent, über mehrere Vaults arbeitend,\n        vollständige Sichtbarkeit, wiederholbar, rückgängig machbar.\n        Alles unten ist im Kern, keine Plugins erforderlich. Installer ist immer noch ~15 MB.",
  },
  cta: ["⬇ v{VERSION} herunterladen (Mac)", "Herunterladen (Windows)", "Alle Plattformen →"],
  sections: [
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.12.1</span>\n          <time>Sep. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.12.1 — Text, der über den Rand lief, und Menüs, die niemand erreichte.</h2>\n        <ul>\n          <li><strong>Eingefügter Text läuft nicht mehr über den Seitenrand.</strong> Stammen die Leerzeichen eines Dokuments aus Word, einer Webseite oder einem Chatverlauf, sind es häufig geschützte Leerzeichen statt gewöhnlicher — in der Datei hinter einer Meldung waren es 119 gegenüber 23 echten. Ein so zusammengeklebter Absatz ist für jede Layout-Engine ein einziges untrennbares Wort und verließ die Spalte schlicht: seitliches Scrollen in der Vorschau, am Rand abgeschnittener Text im exportierten PDF. Behoben in Vorschau, PDF-Export, Druck und HTML-Export. Die Live-Bearbeitung war nie betroffen — genau deshalb wirkte es wie ein Renderfehler. (#293)</li>\n          <li><strong>Die Gliederung füllt die Seitenleiste wieder aus.</strong> Wer den Trenner zog, während die Gliederung sich die Leiste mit einem anderen Panel teilte, und dieses Panel dann schloss, behielt eine vier Zeilen hohe Gliederung in einer dreimal so hohen Leiste — ohne Trenner zum Ziehen, denn Trenner gibt es nur <em>zwischen</em> Panels. Ein Panel allein in der Leiste füllt sie jetzt aus, das unterste nimmt auf, was die darüber übrig lassen, und der Trenner zeigt sich beim Überfahren, statt eine unsichtbare Vier-Pixel-Linie zu bleiben. (#294)</li>\n          <li><strong>Das AppImage lässt sich mit AppImage-Verwaltungen installieren.</strong> Direkt gestartet lief es immer, doch Werkzeuge, die es entpacken — AppManager, Gear Lever —, verweigerten es rundweg: Der Bundler hatte einen absoluten Symlink auf die Festplatte des Build-Rechners eingebacken, einen Pfad, den es auf keinem anderen Computer gibt. (#291)</li>\n          <li><strong>GitLab und selbst gehostete Git-Remotes haben endlich ein Feld für die URL.</strong> Nach „Eigene HTTPS-Git-URL“ kam ein Token-Feld und danach eine leere Fläche: kein Eingabefeld, keine Schaltfläche — während der Hinweis darüber darum bat, einen Clone-Link einzufügen. Für diese Remotes gibt es keine Repository-Liste zum Durchsehen, das Einfügen der URL <em>ist</em> der Weg — und genau der fehlte. Auch Abmelden gab es für sie nicht.</li>\n          <li><strong>Das Schrägstrich-Menü lässt sich mit der Tastatur scrollen.</strong> Pfeil nach unten trug die Auswahl bis zum neunten Eintrag und schien dort stehen zu bleiben; eine mit der Maus gescrollte Liste sprang sofort wieder nach oben — alles unterhalb der Trennlinie, Whiteboards inklusive, war unerreichbar. Das Popup wurde bei jedem Tastendruck zerstört und neu gebaut, was die Scrollposition zurücksetzte und den Code übersprang, der die markierte Zeile im Blick hält.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.12.0</span>\n          <time>Sep. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.12.0 — einklappen, drucken, rückgängig machen.</h2>\n        <ul>\n          <li><strong>Eine Überschrift samt allem darunter einklappen.</strong> Klicken Sie auf den Pfeil am Rand oder nutzen Sie die Falt-Befehle, um einen Abschnitt, alle Abschnitte oder alles unterhalb einer Ebene zu schließen. Das Modell ist ein einfacher Textscan statt einer CodeMirror-Funktion, also funktioniert es im Textarea-Editor von Windows genauso.</li>\n          <li><strong>Der Druck folgt nicht mehr dem App-Design.</strong> Ein dunkles Design wurde bisher dunkel gedruckt — Tinte auf Papier, oder ein PDF, das niemand lesen konnte. Druck und PDF haben jetzt ihre eigene helle Palette, mit einer ausdrücklichen dunklen Option, falls Sie genau das wollten.</li>\n          <li><strong>Nach dem Löschen bleiben acht Sekunden zum Rückgängigmachen.</strong> Die Löschung wird zurückgehalten, statt die Datei irgendwohin zu verschieben: Sie bleibt genau dort, wo sie ist, bis die Zeit abgelaufen ist. Alles, was ein aufgeräumtes Dateisystem braucht — anlegen, umbenennen, Arbeitsbereich wechseln, Fenster schließen — führt die ausstehende Löschung vorher aus.</li>\n          <li><strong>Schnellnotiz, von überall.</strong> Ein systemweites Tastenkürzel (standardmäßig ⌘⌥M) öffnet ein kleines Feld über dem, was Sie gerade tun. Eine Zeile tippen, Enter — und sie landet im Posteingang, ohne dass SoloMD je in den Vordergrund kommt.</li>\n          <li><strong>Ein Aufgabenbereich.</strong> Jedes <code>- [ ]</code> im Arbeitsbereich in einer Liste. Prioritäten und Fälligkeitsdaten werden entweder aus den Emoji von Obsidian Tasks (<code>⏫</code>, <code>📅 2026-09-10</code>) oder aus einer reinen ASCII-Form (<code>!!!</code>, <code>due:2026-09-10</code>) gelesen, damit ein bestehender Vault weiter funktioniert und niemand mitten im Satz zum Emoji-Picker greifen muss. Ein Klick springt zur Zeile, ein Häkchen schreibt die Datei.</li>\n          <li><strong>Word, PDF, HTML und Tabellen importieren.</strong> Die Konverter waren längst in der App, nur ohne Weg dorthin. Es gibt jetzt einen Menüeintrag — und ein bereits vergebener Name wird nicht überschrieben, sondern durch den nächsten freien ersetzt, verglichen ohne Rücksicht auf Groß- und Kleinschreibung, weil Windows und macOS sich uneinig sind, was als Kollision zählt.</li>\n          <li><strong>Eine Tabelle als Raster bearbeiten.</strong> Zeilen und Spalten hinzufügen und entfernen, ohne Striche zu zählen. CJK-Text wird nach Anzeigebreite aufgefüllt, damit der Markdown-Quelltext in einer Monospace-Schrift ausgerichtet bleibt, statt pro chinesischem Zeichen um eine Spalte zu verrutschen.</li>\n          <li><strong>DOCX-Vorlagen.</strong> Deckblatt, Inhaltsverzeichnis, Kopfzeile, Seitenzahlen — drei Voreinstellungen, oder pro Dokument mit einem <code>docx:</code>-Block im Front Matter gesetzt.</li>\n          <li><strong>Nummerierte Formeln und Querverweise.</strong> <code>\\label</code> an einer abgesetzten Formel bekommt eine Nummer und einen Anker; <code>\\eqref</code> wird zu einem Link, der dorthin springt.</li>\n          <li><strong>Ein gelöschter Arbeitsbereichsordner sieht nicht länger aus wie ein leerer Vault.</strong> Wenn der Ordner unter uns verschwand, zeigte der Baum nichts unter seinem eigenen Namen — nicht zu unterscheiden davon, jede Datei darin verloren zu haben. Jetzt steht dort, dass der Ordner fehlt, und die Warnung verschwindet von selbst, sobald er zurück ist.</li>\n          <li><strong>Das Kontextmenü des Dateibaums zeigte Schlüsselnamen.</strong> Vier Zeichenketten waren in keiner Sprache definiert, also stand im Menü <code>explorer.copyGitUrl</code> statt einer Beschriftung — in allen vierzehn. Jetzt überall definiert.</li>\n          <li><strong>Für Agents: <code>list_tasks</code> im MCP-Server.</strong> Jede Checkbox im Arbeitsbereich mit Datei, Zeile und Erledigt-Status, passend zu dem, was der Aufgabenbereich zeigt — damit ein Agent und der Bereich sich nicht darüber uneinig sein können, welche Zeile abzuhaken ist.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.22</span>\n          <time>Sep. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.22 — Dinge, die still nichts taten.</h2>\n        <ul>\n          <li><strong>Datei → Neues Fenster öffnete kein Fenster.</strong> Der Menüeintrag löste ein Ereignis aus, auf das niemand hörte, und war damit seit dem Tag untätig, an dem das native Menü erschien — während dieselbe Aktion aus der Befehlspalette funktionierte, weshalb es sich wie \"es passiert nichts\" anfühlte statt wie ein Fehler. Beide gehen jetzt denselben Weg, und ein Fenster, das sich nicht öffnen lässt, sagt es, statt still zu scheitern.</li>\n          <li><strong>Eine Textdatei öffnete sich nach Live-Bearbeitung leer.</strong> Unter Windows zeigte der Wechsel von einer Markdown-Datei im Live-Modus zu einer .txt-Datei einen leeren Editor, während die Zeilennummern den fehlenden Text weiterzählten. Der Inhalt war nie verloren — Randspalte und Editor wurden zu unterschiedlichen Zeitpunkten gefüllt, und nur die Randspalte gewann. Früher half nur weg- und zurückwechseln; jetzt öffnet sie sich einfach.</li>\n          <li><strong>[[ordner/notiz]]-Links erzeugten eine zweite, leere Notiz.</strong> Ein Wikilink mit einem Ordner darin wurde nie aufgelöst, also legte ein Klick ein Duplikat neben der eigentlich verlinkten Notiz an. Ordnerpfade, Front-Matter-Aliase und seit dem letzten Scan angelegte Dateien werden jetzt alle aufgelöst. Dank an <a href=\"https://github.com/jukejeew\">@jukejeew</a>.</li>\n          <li><strong>Linux: Datei → Beenden, mit Strg+Q.</strong> Kachelnde Fenstermanager blenden die Titelleiste aus, womit weder ein ✕ noch ein offensichtlicher Ausweg bleibt. Ebenfalls von <a href=\"https://github.com/jukejeew\">@jukejeew</a>.</li>\n          <li><strong>Kein Vollbild-Flackern mehr beim Ziehen des Teilers</strong>, und ein eigenes Theme, das es wieder einführen würde, sagt das jetzt beim Laden. Dank an <a href=\"https://github.com/raopan2021\">@raopan2021</a>.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.21</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.21 — die Kürzel-Seite, die Sie nicht sehen konnten.</h2>\n        <ul>\n          <li><strong>Einstellungen → Kürzel öffnete sich als leere Seite.</strong> 4.11.20 lieferte die Neubelegung mit unsichtbarer Einstellungsseite aus: Das Panel zeigt über eine CSS-Whitelist immer nur eine Kategorie, und die neue Kategorie Kürzel wurde nie aufgenommen — also erwischte die Ausblendregel das Markup, und nichts holte es zurück. Alles war da und funktionierte, Sie konnten es nur nicht sehen. Die Whitelist deckt jetzt alle sieben Kategorien ab.</li>\n          <li><strong>Downloads, die Sie selbst prüfen können.</strong> Jede Veröffentlichung trägt jetzt eine <code>SHA256SUMS.txt</code> über alle ihre Dateien, damit Sie prüfen können, dass das Heruntergeladene das ist, was wir gebaut haben.</li>\n          <li><strong>Zu Chromes \"Scan\"-Hinweis unter Windows.</strong> Die Windows-Builds sind noch nicht code-signiert, also prüft Chromes erweiterter Schutz jede neue Version und meldet dann, dass kein Virus gefunden wurde — das ist ein Bestehen, keine Warnung. Davon getrennt löste der x64-Installer von 4.11.20 einen Fehlalarm im maschinellen Lernen von Microsoft Defender aus, weshalb dieser Download kurzzeitig bei 4.11.19 gehalten wurde. Jede Veröffentlichung wird jetzt vor der Auslieferung mit Defender geprüft, und der x64-Installer von 4.11.21 ist sauber — Windows x64 ist also wieder aktuell.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.20</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.20 — die Tastenkürzel gehören jetzt Ihnen.</h2>\n        <ul>\n          <li><strong>Jedes Kürzel der App lässt sich ändern.</strong> Einstellungen → Kürzel listet 37 Aktionen, gruppiert nach Datei / Bearbeiten / Ansicht / Navigieren / Werkzeuge. Auf Ändern klicken, die gewünschte Tastenfolge drücken, und sie gilt sofort — kein Neustart. Sie können eine Aktion ganz entbinden (wenn Sie ⌘E oder ⌘D für etwas anderes zurückhaben wollen, nehmen Sie sie), eine einzelne zurücksetzen oder alle wiederherstellen. Der Versuch, eine bereits vergebene Tastenfolge zu nehmen, wird mit dem Namen der besitzenden Aktion abgelehnt, statt still zwei Besitzer für eine Taste anzulegen.</li>\n          <li><strong>Ein geändertes Kürzel ändert sich überall.</strong> Die gesetzte Tastenfolge steht in den Tooltips der Werkzeugleiste, in der Kürzeltabelle des Markdown-Spickzettels, in der Befehlspalette und — der Teil, auf den es unter macOS wirklich ankommt — in der nativen Menüleiste. Bisher besaß das Menü ⌘S auf Betriebssystemebene, sodass eine Neubelegung von Speichern ⌘S <em>zusätzlich</em> weiter hätte speichern lassen; das Menü wird jetzt mit Ihren Tastenfolgen neu aufgebaut, und eine entbundene Aktion verliert ihren Menü-Kurzbefehl vollständig.</li>\n          <li><strong>Einschließlich des editoreigenen ⌘J.</strong> KI-Umformulierung liegt im Keymap des Editors statt in dem der App und ist ebenfalls neu belegbar — die Änderung erreicht einen bereits geöffneten Editor, nicht erst den nächsten. Tasten, die nur innerhalb eines Popups etwas bedeuten (Pfeile, Tab, Enter, Esc), bleiben fest, ebenso die, die das Betriebssystem besitzt: rückgängig, ausschneiden, kopieren, einfügen.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.19</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.19 — das Telefon ist kein geschrumpfter Desktop mehr.</h2>\n        <ul>\n          <li><strong>Ein Layout für ein Telefon.</strong> Vor dieser Version auf einem 390px-Bildschirm gemessen: Der Dateibaum nahm 250px und die rechte Seitenleiste weitere 260 — von 390 — der Editor war also ein Streifen oder ganz weg; die geteilte Ansicht ließ jeder Hälfte etwa 195px; die Statusleiste brach auf eine zweite Zeile um; und die Werkzeugleiste war ein Band aus 29 Symbolen, durch das man wischte. Die Seitenbereiche sind jetzt Schubladen, die über dem Editor schweben und sich mit einem Tipp daneben schließen, sodass der Editor immer die volle Breite hat. Die Teilung stapelt die Bereiche übereinander statt nebeneinander. Die Werkzeugleiste behält sechs Bedienelemente — Dateibaum, Speichern, die drei Ansichtsmodi, Suche — und ein \"Mehr\", das die Leiste zu einer Fläche aufklappt, in der jedes verbleibende Element ein Symbol <em>und</em> eine Beschriftung hat; nichts wurde unerreichbar. Die Statusleiste behält die Zähler, die sich beim Tippen bewegen, und lässt die Desktop-Referenzwerte weg. Einstellungen sind nicht länger eine 160px-Navigationsspalte neben einer 145px-Spalte. <strong>Tablets bleiben bewusst unangetastet</strong> — das Layout folgt dem Viewport, nicht dem Betriebssystem, also behält ein iPad die Desktop-Anordnung, und ein schmal gezogenes Desktop-Fenster bekommt die des Telefons.</li>\n          <li><strong>Fettdruck, der auf ein Vollbreite-Satzzeichen endet, wird jetzt gerendert.</strong> <code>**限制：**硬链接</code> kam als wörtliche Sternchen heraus. Das schließende <code>**</code> steht nach einem Vollbreite-Doppelpunkt und vor einem Han-Zeichen, und CommonMark sagt, ein Lauf in dieser Position könne nicht schließen — eine Form, die im chinesischen Schreiben überall vorkommt. SoloMD folgt jetzt der CJK-Ergänzung von CommonMark, die diese Regeln als <em>nicht-CJK</em>-Satzzeichen liest. Beide Engines wurden korrigiert: der Renderer für Vorschau und Export und der separate Parser hinter der Live-Bearbeitung, damit die beiden Bereiche sich über dasselbe Dokument nicht uneinig sein können. ASCII bleibt unverändert.</li>\n          <li><strong>Eine mehrzeilige <code>$$</code>-Formel bleibt unter Windows an einem Stück.</strong> Ein Block mit <code>\\begin&#123;aligned&#125;</code> wurde in drei zerlegt, wobei die eingerückte mittlere Zeile als grauer Codeblock gerendert wurde. Der Blockteiler des Windows-Editors kannte ```-Zäune, aber nicht <code>$$</code>, also lief er Zeile für Zeile in die Formel hinein — und jede um vier Leerzeichen eingerückte Zeile, was innerhalb von <code>aligned</code> Routine ist, wurde zu einem eigenen eingerückten Codeblock.</li>\n          <li><strong>Der Export beginnt im Ordner des Dokuments.</strong> Dem Speichern-Dialog wurde nur ein Dateiname übergeben, also griff das System auf den zuletzt verwendeten Ort zurück — exportieren Sie eine Notiz aus Ihrem Notizordner, und der Dialog konnte immer noch im Download-Ordner der Vorwoche aufgehen.</li>\n          <li><strong>Die KI-Einrichtung beim ersten Start bietet jeden Anbieter, und eine Basis-URL.</strong> Sie listete vier Marken, während die Einstellungen sechzehn hatten, und hatte überhaupt kein Adressfeld — wer also einen Relay-Endpunkt oder einen selbst gehosteten Server nutzte, musste den Assistenten ganz überspringen. Sie zeigt jetzt die vollständige Liste mit editierbarer Basis-URL, und Anbieter, die kein Konto brauchen, verlangen keinen Schlüssel mehr. Davon getrennt scheitert die Überprüfung nicht mehr an Endpunkten, die keine Modellliste liefern: Ein Gateway, das für <code>/v1/models</code> 404 zurückgibt, während der Chat einwandfrei läuft, wird jetzt stattdessen mit einem Ein-Token-Chat verifiziert. Ein falscher Schlüssel scheitert weiterhin, wie es sein soll.</li>\n          <li><strong>Der Lesemodus nutzt die von Ihnen gewählte Schrift.</strong> Er deklarierte einen eigenen Serifen-Stack und verschluckte die Einstellung vollständig — der Kommentar im Code behauptete sogar, man könne sie überschreiben. Auf dem Telefon saß seine Schließen-Schaltfläche außerdem auf der ersten Überschrift; sie wandert nach unten rechts, wo ein Daumen sie erreicht.</li>\n          <li><strong>Das macOS-Installationsskript funktioniert wieder.</strong> <code>curl -fsSL https://solomd.app/install.sh | bash</code> scheiterte für jeden macOS-Nutzer mit \"Failed to mount DMG\" — das Skript unterdrückte genau die Ausgabe, aus der es anschließend den Mount-Punkt lesen wollte. Dank an den Melder, dessen Diagnose exakt war.</li>\n          <li><strong>Codeblöcke haben beim Bearbeiten eine Kopieren-Schaltfläche.</strong> Im Live-Modus <em>sieht</em> ein eingezäunter Block gerendert aus — die ```-Zeilen sind versteckt — aber von Hand markiert bekam man weiterhin den Quelltext: die Zäune und, bei einem in einer Liste verschachtelten Block, die zwei Leerzeichen Listeneinrückung vor jeder Zeile. Das in ein Terminal eingefügt, und man darf es von Hand abstreifen. Jeder Codeblock trägt jetzt dieselbe Ein-Klick-Kopieren-Schaltfläche wie der Vorschaubereich, und sie kopiert, was ein Renderer kopieren würde: keine Zäune, die Einrückung des Blocks entfernt, die Einrückung des Codes selbst behalten. Vorhanden an allen drei Stellen, an denen Code gezeigt wird — im Live-Editor, im Vorschaubereich und im Windows-Blockeditor.</li>\n          <li><strong>Ollama auf einem anderen Rechner wird erkannt.</strong> Wenn Sie Ollama auf einem NAS oder einem Rechner im Nebenzimmer betrieben und dessen Adresse in die Basis-URL eintrugen, beharrte Einstellungen → KI auf \"nicht erkannt\" — die Prüfung ignorierte dieses Feld und fragte immer localhost, obwohl der Chat selbst einwandfrei mit Ihrem Server sprach. Sie folgt jetzt der gesetzten Adresse, prüft beim Tippen erneut, sagt genau, was sie angefragt hat, und wenn eine entfernte Maschine nicht antwortet, nennt sie, was zu prüfen ist (ein entfernter Server braucht <code>OLLAMA_HOST=0.0.0.0</code> und einen offenen Port), statt anzubieten, Ollama auf Ihrem Laptop zu installieren.</li>\n          <li><strong>Neuer Anbieter: jeder selbst gehostete OpenAI-kompatible Server</strong> — <code>llama-server</code> von llama.cpp, LM Studio, vLLM, LocalAI, ein internes Gateway. Bisher führte der einzige Weg über den Platz eines anderen Anbieters, und der funktionierte nicht: Ein Schlüssel war Pflicht (also erfand man einen), und ein blankes <code>host:port</code> — genau das, was diese Server beim Start ausgeben — lief in einen 404, weil das <code>/v1</code>-Präfix als bereits getippt angenommen wurde. Jetzt ist das Schlüsselfeld optional, die Adresse wird für Sie vervollständigt, die Modellliste vom Server gelesen, und wenn keine Verbindung zustande kommt, sehen Sie die Antwort des Servers selbst (<code>HTTP 404</code>, Verbindung abgelehnt) plus das, was zu prüfen ist. Auch aus Recipes nutzbar: <code>provider: openai-compat</code> (oder <code>llama-cpp</code> / <code>lmstudio</code> / <code>vllm</code>).</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.17</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.17 — die Option-Kürzel, und ein Hänger, den Linux nicht mehr hinnehmen muss.</h2>\n        <ul>\n          <li><strong>Jedes ⌘⌥-Kürzel funktioniert unter macOS.</strong> macOS faltet Option+Buchstabe in ein anderes Zeichen, bevor der Tastendruck uns überhaupt erreicht — Option+N kommt als \"Dead\" an, Option+P als \"π\", Option+C als \"ç\" — und wir verglichen auf den Buchstaben, also hatten <kbd>⌘⌥N</kbd> (neue Textdatei), <kbd>⌘⌥P</kbd> (Präsentation), <kbd>⌘⌥⇧P</kbd> (als PDF drucken), <kbd>⌘⌥B</kbd> und <kbd>⌘⌥L</kbd> auf einem Mac schlicht nie ausgelöst. Sie vergleichen jetzt auf die physische Tastenposition. Wo wir schon dabei waren: <strong><kbd>⌘⌥C</kbd> kopiert die Auswahl als Markdown</strong> — das eine Kopierformat, das Leute tatsächlich anderswo einfügen, und das einzige ohne Kürzel.</li>\n          <li><strong>Linux: SoloMD wartet nicht länger auf einen Barrierefreiheitsdienst, der nicht antwortet.</strong> Wenn der AT-SPI-Bus des Desktops einen Aufruf annimmt und nie beantwortet, blockieren GTK und WebKit die Oberfläche jeweils für ihren vollen D-Bus-Timeout — 25 s und 30 s — bevor das Fenster zeichnen oder einen Klick annehmen kann. SoloMD fragt diesen Bus jetzt selbst, mit zwei Sekunden Budget, bevor GTK startet: Antwortet er, ändert sich nichts und Screenreader funktionieren genau wie zuvor; antwortet er nicht, starten wir ohne Barrierefreiheit, statt darauf zu warten. Auf einem Prüfstand mit absichtlich verklemmtem Bus gemessen, sank die Zeit vom Start bis zur Benutzbarkeit von 51 s auf 3 s.<br /><strong>Dies ist keine Behebung der auf Arch und Ubuntu gemeldeten Einfrierer (<a href=\"https://github.com/zhitongblog/solomd/issues/253\">#253</a>, <a href=\"https://github.com/zhitongblog/solomd/issues/200\">#200</a>).</strong> Jene erholen sich nie von selbst; dieser Hänger tat es immer, es ist also etwas anderes, und diese Untersuchung läuft weiter. Wenn Sie einen davon erleben, sind die Issues der Ort zum Mitverfolgen.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.16</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.16 — der Cursor bleibt, wo Sie ihn hingesetzt haben.</h2>\n        <ul>\n          <li><strong>Die Schreibmarke springt beim Tippen unter Windows nicht mehr weg.</strong> Wenn irgendetwas die geöffnete Datei von außen anfasste — ein Cloud-Client beim Synchronisieren, ein Sync-Pull, ein Speicher-Umlauf — lud SoloMD den Puffer neu und der Cursor wurde ans andere Ende des Dokuments geworfen. Manchmal kamen gar keine Buchstaben mehr an, weil dasselbe Ereignis eine laufende IME-Komposition unterbrach oder den Fokus aus dem Editor schlug, woraufhin einzelne Tastendrücke als Kürzel gelesen wurden. Eine Behebung dafür gab es seit 4.11.1, sie deckte aber nur den CodeMirror-Editor ab; Windows nutzt ein natives Textfeld und bekam sie nie.</li>\n          <li><strong>Gitee-Sync funktioniert.</strong> Sie konnte sich überhaupt nicht authentifizieren: Wir sendeten den Basic-Auth-Benutzernamen, den GitHub verlangt, und Gitee lehnt ihn rundweg ab — also scheiterte jeder Versuch, egal wie gültig das Token war. Jetzt end-to-end gegen ein echtes Gitee-Repository verifiziert. (#249)</li>\n          <li><strong>Der Agent kann tatsächlich schreiben, wenn Sie es erlauben.</strong> \"Dem Agenten das Schreiben im Vault erlauben\" hatte keine Wirkung — die Schreibwerkzeuge wurden dem Modell nie mitgegeben, also antwortete es, es habe keine. Und Recipe-Läufe endeten auf ihrem Branch, tauchten aber nie unter \"Ausstehende Prüfung\" auf, konnten also weder angenommen noch abgelehnt werden. Beides nachverfolgt von <a href=\"https://github.com/jclg83\">@jclg83</a>. (#247, #248)</li>\n          <li><strong>Rechtschreibprüfung in Ihrer Sprache.</strong> Die Prüfung war auf Englisch festgenagelt, was für alle anderen jedes Wort anstrich. Wählen Sie ein Wörterbuch unter Einstellungen → Schreiben, und legen Sie ein beliebiges Hunspell-Paar aus <code>.aff</code> + <code>.dic</code> in den Ordner, den die Schaltfläche öffnet. (#246)</li>\n          <li><strong>Groß-/Kleinschreibung umwandeln.</strong> <kbd>Shift+F3</kbd> schaltet die Auswahl — oder das Wort unter dem Cursor — durch klein / GROSS / Titel, mit ausdrücklichen Befehlen in der Palette. Auf Gitee angefragt.</li>\n          <li><strong>Typografische Anführungszeichen sind endgültig aus.</strong> Sie in 4.11.11 zur Opt-in-Sache zu machen, änderte nur die Voreinstellung, also sahen alle, die sie bereits hatten, weiterhin eine breite Lücke nach Apostrophen in CJK-Schriften. Jetzt einmalig gelöscht, und es bleibt aus, bis Sie es wieder einschalten. (#251)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.15</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.15 — drei Dinge, die Gitee uns seit Wochen sagte.</h2>\n        <ul>\n          <li><strong>Slash-Befehle taten unter Windows nichts, außer Sie waren in der Live-Bearbeitung.</strong> Windows nutzt ein einfaches Textfeld statt CodeMirror, weil WebView2 bei chinesischer Eingabe Zeichen verliert — und die Ersatz-Autovervollständigung war immer nur an den Blockeditor der Live-Bearbeitung angeschlossen. In 仅编辑 und 分栏 erschien das Popup nie, ließ sich nicht bedienen und konnte nichts einfügen. Es war nicht nur das Slash-Menü: <code>[[</code>-Wikilinks, <code>#</code>-Tags und <code>@</code>-Zitate teilen denselben Auslöser und waren ebenso tot. Alle vier funktionieren jetzt in jedem Modus, und das Popup folgt Ihrer Cursorzeile. (Gitee IK6JCC)</li>\n          <li><strong>Die beiden PDF-Exporte sagen jetzt, was sie tatsächlich erzeugen.</strong> \"Als PDF exportieren\" rastert die Seite, der Text ist also ein Bild — nicht markierbar, nicht durchsuchbar und um ein Mehrfaches größer. Der Export, den die Leute eigentlich wollten, lag direkt darunter unter einem Namen, der keinen Hinweis gab. Sie sind jetzt beschriftet — <em>PDF (Text)</em>, echter markierbarer Text über den Systemdruck, zuerst gelistet und empfohlen; <em>PDF (Bild)</em>, gerastert, aber ohne Dialog gespeichert — in der Werkzeugleiste und in der Befehlspalette. (Gitee IK8QJQ)</li>\n          <li><strong>Word- / EPUB- / ODT- / LaTeX-Exporte entsprechen wieder der Vorschau.</strong> Diese Formate laufen über Pandoc, dem die Rohdatei übergeben wurde, während die Vorschau zuvor einen Durchgang mit Nachsicht-Korrekturen bekam. Eine um zwei Leerzeichen eingerückte Unterliste verschachtelte sich daher auf dem Bildschirm und kam in einer .docx flach heraus. Pandoc sieht jetzt denselben Text wie Sie. (Gitee IJXS8V)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.14</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.14 — der leere Bildschirm, der Ihre Notizen verschluckte.</h2>\n        <ul>\n          <li><strong>Eine gespeicherte Ansicht, die es nicht mehr gab, konnte den ganzen Editor leeren — ohne Rückweg.</strong> Unter Android als \"Notizen lassen sich nicht öffnen\" gemeldet — aber die Notizen <em>öffneten</em> sich: Die Meldung erschien, die Statusleiste zählte die Zeilen, und dann kam nichts. Der Inhaltsbereich zeigt genau eine Sache auf einmal, und der Editor steht als Letzter in der Reihe, also behielt eine als offen markierte gespeicherte Ansicht ihren Platz, auch wenn die Ansicht selbst längst weg war. Und weil die ‹-Zurück-Schaltfläche des Bereichs in genau dem Block lag, der sich ohne Ansicht weigerte zu rendern, blieb nichts zum Anklicken. Weitere Dateien zu öffnen half nicht — jede davon öffnete sich in einen Bereich, der nicht zeichnen konnte. Android traf es am häufigsten, da ein über die System-Dateiauswahl gewählter Ordner das Ansichtenverzeichnis oft nicht lesen kann, aber nichts daran war Android-spezifisch. Der Editor übernimmt jetzt in dem Moment, in dem eine Ansicht nicht mehr auflösbar ist, und die Zurück-Schaltfläche wird immer gerendert. (#245)</li>\n          <li><strong>Das Aurora-Theme wurde überarbeitet.</strong> Aurora-getönte Haarlinien, durchscheinende Panel-Innenflächen, die über dem Verlauf lesbar bleiben, und kein Vollbild-Stroboskop mehr beim Ziehen einer Panelkante. Danke <a href=\"https://github.com/raopan2021\">@raopan2021</a>. (#244)</li>\n          <li><strong>Das Arch-Paket ist wieder aktuell.</strong> <code>solomd-bin</code> ist im AUR verfügbar, und die Paketierung im Repo (die bei 4.1.0 feststeckte) folgt jetzt den echten Veröffentlichungen. Danke <a href=\"https://github.com/gonwe\">@gonwe</a>. (#241)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.13</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.13 — eine richtige Gitea-Integration, 11 neue Themes und zwei Dinge, die still nichts taten.</h2>\n        <ul>\n          <li><strong>Gitea / Forgejo ist jetzt ein vollwertiges Sync-Ziel.</strong> 4.11.12 machte selbst gehostete Synchronisierung <em>erreichbar</em>; dies macht sie echt. Ihr Gitea-Token liegt in einem eigenen Schlüsselbund-Eintrag, Sie können also ein GitHub- und ein Gitea-Token gleichzeitig halten. Ihre Server-URL wird gemerkt und geprüft, bevor Sie sich darauf festlegen. Und SoloMD kann jetzt Ihre Repositories auflisten und das Vault-Repository für Sie anlegen, statt Sie eine Clone-URL einfügen zu lassen. Beigesteuert von <a href=\"https://github.com/JumpingY\">@JumpingY</a>, end-to-end gegen einen echten Gitea-Server verifiziert. (#150)</li>\n          <li><strong>11 neue Community-Themes.</strong> Aurora, Deep Blue, Deep Green, Deep Purple, Frost Blue, Graphite Gray, Ink Blue, Rose Pink, Soft UI, VSCode Modern und Warm Sand — von <a href=\"https://github.com/raopan2021\">@raopan2021</a>, unter Einstellungen → Community-Themes durchsuchen. Neben Ihrer eigenen CSS-Datei gibt es außerdem eine Neu-laden-Schaltfläche, damit Sie ein Theme in Ihrem Editor bearbeiten und ohne Neustart angewendet sehen können. (#239)</li>\n          <li><strong>Im Ordner suchen war tot, wenn Sie je die rechte Seitenleiste ausgeblendet hatten.</strong> Strg/Cmd+Shift+F, die Schaltfläche in der Werkzeugleiste und Ansicht → Im Ordner suchen taten allesamt exakt nichts — und ein erneuter Druck schaltete es still wieder aus. Das Suchpanel liegt in der rechten Seitenleiste, und deren Hauptschalter zum Ausblenden hatte Vorrang, also wurde das Panel dort geöffnet, wo nichts es zeichnen konnte. Alle vier Einstiegspunkte blenden die Seitenleiste jetzt wieder ein. (#209)</li>\n          <li><strong>Cmd gedrückt zu halten skaliert auf einem Mac nicht mehr versehentlich die ganze App.</strong> Zoom-per-Scrollen sprang auf jedes beliebige Scroll-Ereignis an, also konnte ein Trackpad unter einem ruhenden Finger — mit gehaltenem Cmd für ⌘S oder ⌘Tab, wie üblich — die gesamte Oberfläche bis auf Minimalgröße herunterziehen. Beiläufige Bewegung löst jetzt etwa fünfmal seltener einen Zoom aus, während absichtliches Zoomen unverändert bleibt, und unter Einstellungen → Grundlagen gibt es einen Schalter, um die Geste ganz abzuschalten. (#215)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.12</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.12 — Sync läuft auf Ihrem eigenen Server, und Android verspricht nichts mehr, was es nicht kann.</h2>\n        <ul>\n          <li><strong>Selbst gehostete Gitea- / Forgejo-Synchronisierung funktioniert jetzt wirklich.</strong> Die Sync-Engine war nie GitHub-spezifisch — der Einrichtungsbildschirm schon. Die Anbieterauswahl erschien erst, <em>nachdem</em> Sie ein Token gespeichert hatten, und das Speichern prüfte jedes Token gegen github.com und löschte es, wenn das fehlschlug — ein selbst gehostetes Token konnte also nie überleben. Wählen Sie zuerst Ihren Anbieter, und wir fragen github.com nicht mehr nach Tokens, die ihm nicht gehören. End-to-end gegen einen echten Gitea-Server verifiziert. (#229)</li>\n          <li><strong>Android zeigt keine Sync-Einstellungen mehr, die es nicht ausführen kann.</strong> Der Android-Build hat keine Git-Engine, trotzdem zeichnete die App das gesamte Sync-Panel und die Versionsverlauf-Oberfläche — jede Schaltfläche antwortete mit einem kryptischen <code>Command not found</code>, und mit eingeschaltetem Auto-Commit bekamen Sie bei <em>jedem Speichern</em> einen Fehler. Diese Bedienelemente sind unter Android jetzt weg, ersetzt durch eine schlichte Erklärung. (#230)</li>\n          <li><strong>Kein <code>.solomd</code>-Ordner mehr in jedem Ordner, den Sie öffnen.</strong> Einen Ordner nur zum Lesen einer Notiz zu öffnen, hinterließ ein <code>.solomd</code>-Verzeichnis. Dieser Ordner dient dazu, Ihre offenen Tabs zwischen Geräten weiterzureichen, wird also jetzt nur noch in tatsächlich cloud-synchronisierten Ordnern angelegt — in einem gewöhnlichen lokalen Ordner entsteht nichts. (#236)</li>\n          <li><strong>OpenCode Go kommt zur KI-Anbieterliste dazu.</strong> 24 Modelle hinter einem Abonnement, beigesteuert von <a href=\"https://github.com/fengzhoujingshui\">@fengzhoujingshui</a>. (#232, #235)</li>\n          <li><strong>Der Linux-Installer funktioniert auf ARM.</strong> <code>install.sh</code> holte immer nur x86_64-Pakete, also waren die arm64-Builds, die wir längst ausliefern, auf einem Raspberry Pi oder einer ARM-VM unerreichbar. Behoben von <a href=\"https://github.com/jysz\">@jysz</a>. (#220)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.11</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.11 — die Windows-Fenstersteuerung funktioniert wieder, und Vim kann speichern.</h2>\n        <ul>\n          <li><strong>Minimieren und Schließen funktionieren unter Windows wieder.</strong> Die Fensterschaltflächen der vereinheitlichten Titelleiste wurden von einer fehlenden Berechtigung blockiert — Klicks taten nichts, und man musste über die Taskleiste schließen. Behoben und auf einem echten Windows-Build verifiziert. Das Menü Datei hat seinen Eintrag <em>Beenden</em> zurück, Aufklappmenüs schließen sich nicht mehr, wenn Sie darunter scrollen, und der Lesemodus hat jetzt eigene Minimieren-/Schließen-Schaltflächen. (#221, #223)</li>\n          <li><strong>Vim kann speichern und beenden.</strong> <code>:w</code>, <code>:wq</code>, <code>:x</code> und <code>:q</code> tun jetzt, was Sie erwarten — geleitet durch SoloMDs echten Speicher- und Ungespeicherte-Änderungen-Ablauf. Nebenbei schlossen wir eine Lücke, bei der ein direkt nach dem Tippen ausgelöstes Speichern die letzten Tastendrücke verpassen konnte. (#222)</li>\n          <li><strong>Kein Phantom-Leerzeichen mehr nach einem Apostroph.</strong> Die Vorschau ließ ihre typografischen Anführungszeichen standardmäßig an, und manche Schriften zeichneten den geschwungenen Apostroph in voller Breite — was sich wie ein zusätzliches Leerzeichen las. Anführungszeichen werden jetzt genau so gerendert, wie Sie sie tippen; geschwungene sind eine neue Opt-in-Einstellung. (#216)</li>\n          <li><strong>Android: Wörterbuch- und Übersetzungs-Apps tauchen wieder auf.</strong> Beim Markieren von Text werden jetzt Ihre installierten <code>PROCESS_TEXT</code>-Apps angeboten (Offline-Wörterbücher, Übersetzer). (#224)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.10</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.10 — eine Titelleiste unter Windows, und drei erbetene Korrekturen.</h2>\n        <ul>\n          <li><strong>Windows bekommt eine vereinheitlichte Titelleiste.</strong> Drei Reihen Fensterrahmen fallen zu einer zusammen — Fenstersteuerung, Tabs und Werkzeugleiste teilen sich eine Reihe, wie in der Mac-App. Snap Layouts funktionieren weiterhin über die Maximieren-Schaltfläche, und der MSI-Installer bekam ein ordentliches Branding. </li>\n          <li><strong>Alles auswählen kann den Windows-Editor nicht mehr einfrieren.</strong> Strg+A wird im Blockeditor jetzt von SoloMD selbst behandelt, statt mit der nativen Textarea zu kämpfen. (#189, #210)</li>\n          <li><strong>Codeblöcke brechen in der Live-Bearbeitung um, und PDFs schneiden sie nicht mehr ab.</strong> Die Einstellung \"lange Zeilen in Codeblöcken umbrechen\" gilt jetzt auch beim Bearbeiten, und der PDF-Export schneidet lange Codezeilen nicht mehr ab. (#211)</li>\n          <li><strong>Verschachtelte Listen in nummerierten Listen behalten ihre Form.</strong> Eine Aufzählungs-Unterliste unter einer geordneten Liste fällt nicht mehr auf eine Ebene zusammen. (#213)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.9</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.9 — Zoom, der zielsicher bleibt, und vier erbetene Annehmlichkeiten.</h2>\n        <ul>\n          <li><strong>⌘+/⌘- -Zoom zerstört unter macOS nicht mehr die Klickgenauigkeit.</strong> Der Zoom läuft jetzt über die System-Webview (wie bei Safari), also landet die Schreibmarke bei jeder Zoomstufe genau unter dem Zeiger. (#192)</li>\n          <li><strong>Die Seitenleiste kann nicht mehr ausgeblendet feststecken.</strong> Die Gliederung — oder irgendeinen Bereich — über das Kürzel, die Einstellungen oder die Tableiste zu öffnen, holt jetzt auch die automatisch ausgeblendete Seitenleiste zurück. (#207)</li>\n          <li><strong>Die Befehlspalette spricht Ihre Sprache.</strong> Alle 85 Befehle folgen Einstellungen → Sprache über 14 Sprachen hinweg; die Suche trifft sowohl den übersetzten als auch den englischen Namen. (#177)</li>\n          <li><strong>Neue Optionen:</strong> ein Schalter für einen durchgehenden (nicht blinkenden) Cursor (#193) und eine eigene Code-Schriftart (#190). <strong>Aus der Vorschau kopierte Tabellen behalten ihre Rahmen</strong>, wenn sie in E-Mail-Programme eingefügt werden. (#189)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.8</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.8 — die geteilte Ansicht fluchtet, Positionen bleiben.</h2>\n        <ul>\n          <li><strong>Die geteilte Ansicht bleibt auf gleicher Höhe.</strong> Editor und Vorschau folgen einander jetzt bei jeder Scrollposition pixelgenau — weich umbrochene Absätze, Bilder und rohe HTML-Blöcke ziehen die beiden Hälften nicht mehr auseinander, und Zeilennummern kleben an ihren Zeilen. (#203)</li>\n          <li><strong>Ihre Scrollposition übersteht Tabwechsel.</strong> Unter Windows setzt Weg- und Zurückwechseln die Ansicht nicht mehr an den Anfang zurück — in den Modi Bearbeiten, Geteilt und Live gleichermaßen. (#169)</li>\n          <li><strong><code>==Hervorhebung==</code> wird in der Live-Bearbeitung gerendert.</strong> Gleiche Behandlung wie fett/kursiv: gestaltet abseits der Cursorzeile, roher Quelltext beim Bearbeiten; Codeblöcke bleiben wortgetreu. Der Schreibmaschinenmodus zentriert die Cursorzeile jetzt auch im Windows-Editor. (#199)</li>\n          <li><strong>Sprungmarken der Gliederung jenseits von <code>az</code> sind korrigiert.</strong> Lange Dokumente zeigen keine <code>aundefined</code>-Marker mehr. (#206)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.7</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.7 — ein verlässlicher Windows-Installationsweg.</h2>\n        <ul>\n          <li><strong>MSI ist jetzt der einzige installierte Windows-Kanal.</strong> SoloMD installiert nach <code>C:\\Program Files\\SoloMD</code>; das portable ZIP bleibt ohne Installation verfügbar.</li>\n          <li><strong>Alte Installationen pro Benutzer werden sicher migriert.</strong> Beim ersten Start aus dem MSI-Pfad prüft und entfernt SoloMD die stillgelegte NSIS-Installation unter <code>%LOCALAPPDATA%\\SoloMD</code>, samt ihrer veralteten Verknüpfungen und der Taskleisten-Anheftung.</li>\n          <li><strong>Ihre Arbeit und Ihre Einstellungen bleiben unangetastet.</strong> Die Migration entfernt niemals <code>%APPDATA%\\app.solomd</code> oder Benutzerdokumente.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.6</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.6 — Windows behält nach dem Upgrade das neue Symbol.</h2>\n        <ul>\n          <li><strong>Taskleisten-Anheftungen, Verknüpfungen und die laufende App teilen sich jetzt eine stabile Identität.</strong> Windows fällt nach einem Upgrade nicht mehr auf ein altes oder leeres zwischengespeichertes Symbol zurück.</li>\n          <li><strong>Dies ist ein gezielter Windows-Hotfix.</strong> Die macOS- und Android-Pakete werden für einheitliche Downloads neu erstellt; ihr Plattformverhalten bleibt unverändert.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.5</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.5 — eingebettetes HTML funktioniert jetzt in der Live-Bearbeitung.</h2>\n        <ul>\n          <li><strong>Block-HTML wird dort gerendert, wo Sie schreiben.</strong> Container wie <code>&lt;div&gt;</code>, <code>&lt;table&gt;</code> und <code>&lt;details&gt;</code> fallen jetzt in ihr gerendertes Ergebnis zusammen, sobald die Schreibmarke den Block verlässt.</li>\n          <li><strong>Inline-HTML verhält sich wie Markdown-Formatierung.</strong> Tags wie <code>&lt;strong&gt;</code>, <code>&lt;sup&gt;</code>, <code>&lt;mark&gt;</code> und <code>&lt;kbd&gt;</code> zeigen ihre visuelle Bedeutung, statt als störender Quelltext stehen zu bleiben.</li>\n          <li><strong>Der Quelltext ist immer einen Klick entfernt.</strong> Die Schreibmarke zurück in ein HTML-Fragment zu bewegen, legt das exakte Markup zum Bearbeiten frei.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.4</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.4 — das neue Zeichen erreicht den Fensterrahmen.</h2>\n        <ul>\n          <li><strong>Die Titelleiste trägt jetzt das neue Portal-Zeichen.</strong> Der alte <code>#MD</code>-Schriftzug ist aus der App-Werkzeugleiste verschwunden.</li>\n          <li><strong>Der Über-Dialog passt dazu.</strong> Beide Oberflächen rendern jetzt eine gemeinsame Marken-Komponente, damit künftige Identitätsänderungen nicht auseinanderdriften können.</li>\n          <li><strong>macOS-Dateisymbole sind enthalten und registriert.</strong> Das signierte, notarisierte universelle DMG ordnet Markdown-Dateien dem neuen Portal-Dokumentsymbol in warmem Papierton zu.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.3</span>\n          <time>Aug. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.3 — ein neues Gesicht, dazu zwei frische Korrekturen.</h2>\n        <ul>\n          <li><strong>SoloMD hat eine neue visuelle Identität.</strong> Das neue orange <code>#</code>-Portal-App-Symbol wird jetzt einheitlich unter macOS, Windows, Linux, iOS, Android, im App Store und auf der Website ausgeliefert.</li>\n          <li><strong>Markdown-Dateien sind auf einen Blick erkennbar.</strong> Das Standard-Dokumentsymbol ist ein warmes Papierblatt mit orangefarbenem Eselsohr und dem passenden <code>#</code>-Portal-Zeichen.</li>\n          <li><strong>Der Vim-Modus funktioniert unter Windows wieder.</strong> Vim zu aktivieren schaltet den Editor jetzt sofort auf CodeMirror um, während der normale Windows-Editor seinen IME-sicheren Textarea-Weg behält.</li>\n          <li><strong>Codeblöcke haben eine Kopieren-Schaltfläche.</strong> Jeder gerenderte eingezäunte Block bekommt oben rechts eine angeheftete, barrierefreie Ein-Klick-Kopieraktion.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.2</span>\n          <time>Juli 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.2 — vier kleine Korrekturen, die Sie gestört haben.</h2>\n        <ul>\n          <li><strong>Codeblöcke können umbrechen.</strong> Eine neue Einstellung bricht lange Codezeilen weich um, statt eine horizontale Bildlaufleiste zu zeigen — und PDF/Druck bricht jetzt immer um, damit breiter Code auf Papier nie abgeschnitten wird.</li>\n          <li><strong>Tabs merken sich, wo Sie waren.</strong> Zu einem Tab zurückzuwechseln setzt die Ansicht nicht mehr an den Anfang zurück, wenn Sie gescrollt hatten, ohne zu klicken; auch die Zeilennummern bleiben stehen.</li>\n          <li><strong>Vims <code>j</code>/<code>k</code> respektieren Tabellen.</strong> Einzelschritte landen an der Kante eines eingeklappten Tabellen-/Mathe-/Mermaid-Blocks und klappen ihn auf — genau wie die Pfeiltasten — statt darüber hinwegzuspringen.</li>\n          <li><strong>Vollständige Dateinamen im Explorer.</strong> Eine neue Einstellung bricht lange Namen um, statt sie in der Mitte mit Auslassungspunkten zu kürzen.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.1</span>\n          <time>Juli 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.1 — der Cursor bleibt, wo Sie ihn hingesetzt haben.</h2>\n        <ul>\n          <li><strong>Cursorsprung bei chinesischer IME behoben.</strong> Mitten im Absatz zu bearbeiten und direkt danach eine Pinyin-Komposition zu beginnen, konnte die Schreibmarke an den Dokumentanfang werfen und halb zusammengesetzte Buchstaben dort stranden lassen — ein Wettlauf einer entprellten Synchronisierung, die mitten in der Komposition das ganze Dokument ersetzte. Die Komposition wird jetzt nie unterbrochen, und externe Aktualisierungen lassen die Schreibmarke an Ort und Stelle.</li>\n          <li><strong>Die Update-Meldung entführt Ihren Browser nicht mehr.</strong> Eine neue Version zu erkennen zeigt jetzt eine 12 Sekunden lange, anklickbare Meldung; es öffnet sich nichts, außer Sie klicken darauf — und jeder Update-Link (Meldung, Prüfung in den Einstellungen, Über-Dialog) führt zu solomd.app statt zu GitHub.</li>\n          <li><strong>KI-Modellkatalog aktualisiert</strong> über alle 14 Anbieter (GPT-5.6-Familie, Grok 4.5, Claude Fable 5 / Opus 4.8, Gemini 3.6, GLM-5.2, Kimi K3 und weitere; stillgelegte DeepSeek-v2-Endpunkte entfernt).</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11</span>\n          <time>Juli 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11 — kaputte Tabellen reparieren sich selbst.</h2>\n        <ul>\n          <li><strong>Fehlerhafte Tabellen werden trotzdem gerendert.</strong> KI-Exporte und PDF-zu-Markdown-Werkzeuge geben oft eine Trennzeile aus, die nicht zur Kopfzeile passt (eine <code>|---|</code>-Zelle zu viel, eine zu wenig, eine leere Zelle) — und die ganze Tabelle fiel still zu wörtlichem <code>| … |</code>-Text zusammen. SoloMD repariert die Trennzeile jetzt im Fluge, wie Typora und Obsidian, und behält die Ausrichtung jeder Spalte. Beispiele in Codeblöcken bleiben unangetastet.</li>\n          <li><strong>Nummerierte Abschnitte können zu Überschriften werden (opt-in).</strong> Berichte nummerieren Abschnitte oft als reinen Text — <code>6.2 Exportlizenzierung</code> — ohne <code>#</code>. Eine neue Einstellung (standardmäßig aus) hebt solche Zeilen nach Tiefe zu echten Überschriften an: <code>6.2</code> → h2, <code>6.2.1</code> → h3. Geordnete Listen, Sätze mit Dezimalzahlen und einzelne Zahlen werden nie angefasst.</li>\n          <li><strong>Der Export ohne Oberfläche entspricht der App.</strong> Die CLI (<code>solomd-export</code>, neues Flag <code>--number-headings</code>) und das MCP-Werkzeug <code>export_note</code> (neues Argument <code>number_headings</code>) führen jetzt exakt dieselbe Markdown-Vorverarbeitung aus wie die Vorschau in der App und der DOCX-Export — eine Engine, überall identische Ausgabe.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.10</span>\n          <time>Juli 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.10 — PlantUML + ein Schieberegler für die Vorschaubreite.</h2>\n        <ul>\n          <li><strong>PlantUML-Diagramme (opt-in).</strong> <code>```plantuml</code>-Zäune werden in der Vorschau und in der Live-Bearbeitung als Diagramme gerendert, über einen konfigurierbaren PlantUML-Server. Standardmäßig aus — Ihre Notizen verlassen die Maschine nie, außer Sie schalten es ein; richten Sie es auf einen selbst gehosteten Server, um das Rendern im eigenen Netz zu halten.</li>\n          <li><strong>Die Vorschaubreite gehört Ihnen.</strong> Die Spaltenbreite von Vorschau und Lesemodus ist jetzt ein Schieberegler (480–1600px, vorher feste 760px). \"An Breite anpassen\" dehnt weiterhin auf das Fenster.</li>\n          <li><strong>Tabellen fangen die Schreibmarke nicht mehr ein.</strong> In der Live-Bearbeitung sprangen ↑/↓ komplett über gerenderte Tabellen hinweg — und konnten ganze Absätze darunter überspringen. Die Schreibmarke läuft jetzt jede Zeile ab, tritt in eine Tabelle (oder einen Mathe-/Mermaid-Block) ein, um deren Quelltext zu bearbeiten, und der Block wird beim Verlassen neu gerendert.</li>\n          <li><strong>Zeilennummern in Codeblöcken, korrigiert.</strong> Nummerierte Codeblöcke verdoppeln ihren Zeilenabstand nicht mehr, Kommentare im C-Stil <code>/** */</code> verschlucken nicht mehr den Rest des Blocks in Zeile 1, und der WYSIWYG-Editor beachtet jetzt dieselbe Zeilennummern-Einstellung wie die Vorschau.</li>\n          <li><strong>Klicks bleiben Klicks (4.10.1).</strong> Direkt nach einem Tabwechsel zu klicken — während Diagramme/Bilder noch gerendert wurden — konnte mehrere Zeilen markieren, statt die Schreibmarke zu setzen. Die Schreibmarke bleibt jetzt dort, wo Sie gedrückt haben, selbst wenn sich das Layout mitten im Klick verschiebt.</li>\n          <li><strong>Verlinkte Dateien mit der Standard-App öffnen (4.10.2).</strong> Ein Markdown-Link auf ein lokales PDF oder eine Office-Datei (<code>[bericht](./bericht.pdf)</code>) öffnet jetzt in der Standard-App Ihres Systems, statt nach Markdown konvertiert zu werden. Neue Einstellung, standardmäßig an; Links auf <code>.md</code>, Text und Bilder öffnen weiterhin in SoloMD.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.9</span>\n          <time>Juli 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.9 — echte Ordner unter Android + Editor-Feinschliff.</h2>\n        <p class=\"lead\">\n          Die 4.9-Reihe lässt SoloMD Ihre <strong>echten Ordner unter\n          Android</strong> öffnen und bearbeiten — keine Kopie in einer Sandbox.\n          Unter Android 11+ (einschließlich Honor / Huawei <strong>Magic\n          OS</strong>, wo die Alle-Dateien-Berechtigung nichts gewährt) nutzt\n          SoloMD jetzt das <strong>Storage Access Framework</strong>: einmal\n          einen Ordner wählen, dann die tatsächlichen <code>.md</code>-Dateien\n          an Ort und Stelle lesen und schreiben, zurückgespeichert über den\n          Content-Provider des Systems.\n        </p>\n        <ul>\n          <li><strong>Android-Ordner-Vault (SAF).</strong> Einen echten Ordner öffnen, Dateien an Ort und Stelle bearbeiten, mobiles Layout über die volle Breite.</li>\n          <li><strong>Speichern unter korrigiert.</strong> Es schrieb unter Android leere Dateien — jetzt landet der Inhalt in der Datei, die Sie wählen.</li>\n          <li><strong>Suchen (Strg/⌘+F) scrollt beim Tippen mit.</strong> Der Editor springt schon beim Tippen zum ersten Treffer, wie Ihr Browser — kein \"nichts gefunden\" mehr bei langen Notizen.</li>\n          <li><strong>Pfeiltasten in der Live-Bearbeitung überqueren Blöcke.</strong> ↑/↓/←/→ bewegen die Schreibmarke jetzt zwischen Absätzen im Windows-Blockeditor — und seit 4.9.6 beachten sie weich umbrochene Zeilen, sodass ↑ in einem langen Absatz nicht mehr darüber hinwegspringt.</li>\n          <li><strong>Zeilennummern unter Windows (4.9.6).</strong> Die Einstellung \"Zeilennummern anzeigen\" funktioniert jetzt im Windows-Editor, mit einer Randspalte, die bei Wortumbruch ausgerichtet bleibt.</li>\n          <li><strong>Mermaid-Diagramme als PNG exportieren (4.9.6).</strong> Auf ein Diagramm klicken → PNG exportieren oder Bild kopieren, in doppelter Auflösung mit zum Theme passendem Hintergrund.</li>\n          <li><strong>Der Speichern-Dialog übernimmt Ihren Titel (4.9.6).</strong> Eine nie gespeicherte Notiz, die mit <code># Überschrift</code> beginnt, füllt \"Überschrift.md\" vor — Schluss mit dem Neutippen von Dateinamen.</li>\n          <li><strong>Linux-Startfehler behoben.</strong> Das AppImage bricht auf manchen Intel-/Mesa-Konfigurationen nicht mehr mit <code>EGL_BAD_PARAMETER</code> ab.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.7</span>\n          <time>Juni 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.7 — Windows bekommt einen brandneuen Editor.</h2>\n        <p class=\"lead\">\n          <strong>Nur Windows.</strong> SoloMD unter Windows nutzt jetzt einen\n          vollständig neu gebauten <strong>Blockeditor</strong> anstelle von\n          CodeMirror. Das <code>contentEditable</code> von WebView2 verschluckte\n          das <strong>erste Zeichen bei CJK-/IME-Eingabe</strong> und\n          <strong>verdoppelte Satzzeichen</strong> (am schlimmsten mit Sogou) —\n          ein Fehler, der sich innerhalb von CodeMirror nicht beheben ließ, weil\n          er in WebView2 selbst steckt. Der neue Editor tippt jeden Block durch\n          eine native <code>&lt;textarea&gt;</code> auf dem IME-Pfad des\n          Betriebssystems, damit verschluckte Zeichen und verdoppelte\n          Satzzeichen verschwunden sind.\n        </p>\n        <p>\n          Der neue Windows-Editor behält <strong>vollen Funktionsumfang</strong>:\n          Live-Markdown-Vorschau, Autovervollständigung &amp; Slash-Befehle\n          (<code>/</code>), Fokus- &amp; Schreibmaschinenmodus, intelligente\n          Listenfortsetzung, KI-Umformulierung (<code>Strg+J</code>), Suchen &amp;\n          Ersetzen im Dokument (<code>Strg+F</code>), Bild aus der Zwischenablage\n          einfügen, Aufgaben-Checkboxen umschalten, Rückgängig / Wiederholen,\n          Tab-Einrückung, Rechtschreibprüfung und Wortumbruch.\n        </p>\n        <p style=\"opacity:.8;\">\n          <strong>macOS, Linux, iOS und Android sind nicht betroffen</strong> —\n          sie behalten den bestehenden CodeMirror-Editor. Ebenfalls in 4.7: Die\n          Befehlspalette springt nicht mehr, wenn Sie die Liste überfahren oder\n          mit dem Rad scrollen (#93).\n        </p>\n        <p class=\"version-row\" style=\"margin-top:24px;\">\n          <span class=\"version-tag\">v4.9</span>\n          <time>Juli 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.9 — Android öffnet Ihren echten Vault.</h2>\n        <p class=\"lead\">\n          Unter Android war SoloMDs einzig frei lesbarer Ordner bisher eine\n          Sandbox unter <code>/Android/data</code>, die auf einem Telefon ohne\n          Root kein Dateimanager erreicht — Sie konnten die App also nie auf\n          Ihren tatsächlichen Notizordner richten. 4.9 fügt\n          <strong>Zugriff auf alle Dateien</strong> hinzu: einmal gewähren, und\n          <strong>Ordner öffnen</strong> lässt Sie zu einem echten Vault\n          irgendwo auf dem Gerät navigieren (<code>Documents</code>, ein\n          Syncthing-/Dropbox-Ordner, eine SD-Karte) und <strong>Dateien an Ort\n          und Stelle bearbeiten</strong> — ohne Kopieren in die Sandbox.\n          Dateibaum, Suche, Versionsverlauf und Speichern arbeiten alle mit\n          Ihren echten Pfaden (#148, #151).\n        </p>\n        <p style=\"margin-top:14px;\">\n          Ebenfalls in 4.9 ein Durchgang durch gemeldete Fehler.\n          <strong>Das macOS-Fenster lässt sich wieder an seiner Titelleiste\n          ziehen</strong> (#153) — der Zieh-Aufruf war seit dem Erscheinen der\n          vereinheitlichten Titelleiste still von einer fehlenden Berechtigung\n          abgelehnt worden; Doppelklick zum Zoomen ist ebenfalls zurück.\n          <strong>Der Dialog \"Datei auf der Festplatte geändert\" unterbricht\n          unter Android nicht mehr das Tippen</strong> (#148) — die eigenen\n          Speichervorgänge der App wurden für externe Änderungen gehalten, weil\n          Android Dateiereignisse Sekunden zu spät liefert; Änderungen werden\n          jetzt stattdessen an der Änderungszeit der Datei beurteilt. Der\n          Hinweis auf ein verfügbares Update öffnet jetzt die Downloadseite von\n          solomd.app (in Festlandchina erreichbar, mit dem Gitee-Spiegel) statt\n          GitHub (#154), und der wirkungslose Menüeintrag \"Im Finder zeigen\"\n          wird auf Telefonen ausgeblendet.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.11</strong> — drei gemeldete Fehler, behoben.\n          <strong>Android kann wieder Dateien öffnen</strong> (#148): Dateien,\n          die ein Dateimanager, \"Öffnen mit\" oder die App-eigene Auswahl\n          übergibt, kommen als <code>content://</code>-URIs an, die kein\n          Dateisystemaufruf lesen kann — sie werden jetzt in den SoloMD-Ordner\n          importiert (unter Beibehaltung des ursprünglichen Dateinamens oder\n          benannt nach der ersten Überschrift des Dokuments) und normal\n          geöffnet, entsprechend dem Ablauf der iOS-Dateien-App.\n          <strong>GitHub-Sync pusht nicht mehr nach <code>main</code>, während\n          es von <code>master</code> pullt</strong> (#147) — ein zweites Gerät\n          konnte dauerhaft feststecken und die Pushes des ersten nie sehen; das\n          Pull normalisiert den Branch jetzt genauso wie das Push, mit einem\n          Rückfall für alte Nur-master-Remotes. Und <strong>das Schließen eines\n          Tabs führt zum benachbarten Tab</strong> zurück, statt zum ersten in\n          der Liste zu springen (#149 — Ursache vom Melder beigesteuert, danke!).\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.10</strong> — Durchgang für den Alltag.\n          <strong>Strg+A wählt endlich das ganze Dokument aus</strong> im\n          Windows-Live-Editor (bisher hörte es beim aktuellen Absatz auf), damit\n          Alles-auswählen → kopieren / löschen / überschreiben sich wie in jedem\n          anderen Editor verhält. <strong>Eine gelöschte Datei oder ein Ordner\n          wandert jetzt in den Papierkorb des Systems</strong>, statt dauerhaft\n          gelöscht zu werden (#112), und einzelne Einträge lassen sich aus der\n          Liste zuletzt verwendeter Dateien entfernen. Eine neue Einstellung\n          <strong>„einzelner Zeilenumbruch = Zeilenumbruch“</strong> hält\n          Vorschau, Windows-Live-Editor und jeden Export (PDF, DOCX, Pandoc)\n          darüber einig, was Enter bedeutet (#141). <strong>Schriftgröße &amp;\n          -art gelten jetzt überall</strong> — Live-Bearbeitungsblöcke,\n          Vorschaubereich und Lesemodus (#143). Ein Tabwechsel <strong>behält\n          Cursor und Scrollposition</strong> (#144), „beim Start im Lesemodus\n          öffnen“ funktioniert wieder mit ausgeschaltetem Tab-Wiederherstellen,\n          die Einstellungsseiten teilen sich nicht mehr eine Scrollposition, und\n          die <strong>KI-Umformulieren-Schaltfläche</strong> der Werkzeugleiste\n          funktioniert unter Windows (#126).\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.9</strong> — das Öffnen von Dateien unter iOS, wirklich\n          behoben. Eine Markdown-Datei aus der <strong>Dateien-App</strong>, per\n          AirDrop oder aus einer anderen App zu öffnen, scheitert nicht mehr mit\n          \"No such file or directory\" (#139) — das Teilen-Menü übergab eine\n          prozentkodierte <code>file://</code>-URL, die nie dekodiert wurde.\n          <strong>Zuletzt verwendete Dateien überstehen App-Updates</strong>\n          (iOS verschiebt den App-Container bei jedem Update; gespeicherte Pfade\n          werden automatisch neu verankert), <strong>Ordner öffnen</strong>\n          heftet den Arbeitsbereich jetzt an SoloMDs Dokumentenordner, und die\n          <strong>Tableiste lässt sich per Wischen scrollen</strong>. Auch auf\n          dem Desktop: lokale <strong>SVG-Vorschauen</strong> bleiben über\n          Fenster hinweg sichtbar (#142, danke @beihai23).\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.1</strong> — Korrekturen. <strong>Suchen &amp;\n          Ersetzen</strong> ist wieder auffindbar (ein Eintrag in der\n          Befehlspalette; es lag immer hinter Strg+F, #137). Ein Klick auf einen\n          relativen <code>.md</code>-Link in einem <strong>WSL</strong>-Vault\n          scheitert nicht mehr mit „os error 3“ (#138). Ein angehefteter Start\n          im <strong>Lesemodus</strong> mit ausgeschaltetem Tab-Wiederherstellen\n          öffnet kein leeres Fenster mehr (#128). Das\n          <strong>macOS-App-Symbol</strong> ist jetzt ein ordentliches\n          abgerundetes Quadrat mit Rand (#111). Und ein abgelaufenes oder\n          widerrufenes <strong>GitHub-Sync</strong>-Token fordert Sie jetzt zum\n          Neuverbinden auf, statt einen rohen 401 zu werfen.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.0</strong> — <strong>Bild-Hosting (图床)</strong>. Fügen\n          Sie ein Bild ein, ziehen Sie es hinein oder wählen Sie es aus, und\n          SoloMD kann es jetzt zu einem externen Bildhoster hochladen und die\n          zurückgegebene URL einsetzen — statt es nur in einen lokalen Ordner zu\n          kopieren, wie Typora / MarkText. Fünf Backends:\n          <strong>PicGo</strong> (lokaler Server), ein <strong>eigener\n          Befehl</strong> (PicGo-Core / uPic / ein beliebiges Skript),\n          <strong>SM.MS</strong>, <strong>S3-kompatibel</strong> (Aliyun OSS /\n          Tencent COS / Cloudflare R2 / MinIO) und ein <strong>GitHub-Repo +\n          CDN</strong>. Dazu „Bild aus URL einfügen“ und ein Befehl „alle\n          lokalen Bilder dieser Notiz hochladen“. Der automatische Upload beim\n          Einfügen fällt auf eine lokale Kopie zurück, wenn der Hoster nicht\n          erreichbar ist. Einzurichten unter Einstellungen → Schreiben.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.4</strong> — <strong>Rücktaste / Entfernen</strong> sind\n          im Windows-Editor wieder verlässlich. Jeder Absatz ist dort ein eigenes\n          Textfeld, also traf ein Druck auf die Rücktaste ganz am Anfang eines\n          Blocks (oder Entfernen ganz an seinem Ende) auf die Feldkante und tat\n          nichts — Löschen fühlte sich nach Glückssache an. Diese Druckvorgänge\n          an den Grenzen wirken jetzt auf das ganze Dokument, verbinden Absätze\n          oder entfernen die Leerzeile wie in einem normalen Editor, und Cursor\n          und Fokus folgen mit.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.3</strong> — der <strong>PDF-Export</strong> stürzt nicht\n          mehr bei Themes oder Inhalten ab, die moderne CSS-Farbfunktionen\n          nutzen (<code>color()</code>, <code>oklch()</code>,\n          <code>color-mix()</code>), und ein fehlgeschlagener Export lässt das\n          Fenster nicht mehr eingefroren oder zoombar zurück (#115). Dazu: die\n          <strong>Scroll-Synchronisierung der geteilten Ansicht</strong>\n          funktioniert unter Windows wieder — Editor und Vorschau hatten nach\n          dem Umbau des Windows-Editors in 4.7 aufgehört, einander zu folgen.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.2</strong> — der Dateibaum bekommt eine <strong>in der\n          Breite verstellbare Seitenleiste</strong> (Kante ziehen,\n          180–600&nbsp;px), <strong>Symbole je Dateityp</strong> und eine\n          Kürzung langer Dateinamen mit Auslassungspunkten in der Mitte; die\n          macOS-Titelleiste überlappt die App-Werkzeugleiste nicht mehr (#121).\n          Dazu eine <strong>PDF-Export-Korrektur</strong>: Fließabsätze und\n          Listeneinträge werden an Seitenumbrüchen nicht mehr halbiert.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.1</strong> — die Live-Vorschau rendert jetzt\n          Aufzählungslisten, Aufgaben-Checkboxen und horizontale Linien (nicht\n          nur Überschriften) unter macOS / Linux / iOS / Android; der\n          Quelltextmodus ist wieder wirklich schlicht (Überschriften werden\n          nicht mehr vergrößert, wenn die Live-Vorschau aus ist). Dazu:\n          <strong>Pfad / relativen Pfad kopieren</strong> im Dateibaum (#120)\n          und eine Schaltfläche <strong>Ordner schließen</strong> (#118), eine\n          lesbare Spalte über <strong>Editorbreite begrenzen</strong> (#109),\n          und der An-Breite-anpassen-Schalter funktioniert jetzt im Lesemodus\n          (#117).\n        </p>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.6</span>\n          <time>Juni 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.6 — die Wissensgraph-Hälfte, gebaut.</h2>\n        <p class=\"lead\">\n          Ein vollständiger <strong>Umbau von Designsystem und\n          Vue-Komponentenbibliothek</strong> (warm-neutrale Flächen, oranger\n          Akzent <code>#ff9f40</code>) und eine <strong>vereinheitlichte\n          macOS-Titelleiste</strong> (die Ampelknöpfe in die Werkzeugleiste\n          eingebettet) — dazu die sieben strukturellen Funktionen, die früher\n          das Eine waren, das ein Wissensgraph-Editor wie Tolaria konnte und\n          SoloMD nicht. Alles auf der Festplatte als schlichtes\n          <code>.md</code> / YAML. Kein neues Dateiformat.\n        </p>\n        <div class=\"pillars\">\n          <div class=\"pillar\">\n            <h3>Eigenschaften-Inspektor (<code>⌘⇧I</code>)</h3>\n            <p>\n              Ein eigener Front-Matter-Editor — Auswahlfelder für Datum,\n              Beziehung, Status und Tags — statt YAML von Hand zu bearbeiten.\n              Schreibt direkt in das Front Matter der Notiz zurück.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Typgesteuerte Seitenleiste</h3>\n            <p>\n              <code>type:&lt;Name&gt;</code>-Notizen werden zu vollwertigen,\n              einklappbaren Abschnitten der Seitenleiste (Typen als Linsen), je\n              mit eigenem Symbol, eigener Farbe, Reihenfolge und angehefteten\n              Eigenschaften.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Typisierte Beziehungen</h3>\n            <p>\n              Front-Matter-Felder <code>belongs_to</code> /\n              <code>related_to</code> / <code>has</code> mit\n              <strong>automatischen Umkehrungen</strong> — deklarieren Sie eine\n              Seite, die andere löst sich selbst auf.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Beziehungsgraph („Nachbarschaft“)</h3>\n            <p>\n              Ein Explorer je Notiz für ausgehende <em>und</em> umgekehrte\n              Beziehungen — laufen Sie den Graphen Sprung für Sprung ab, von\n              welcher Notiz Sie auch gerade ausgehen.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Gespeicherte gefilterte Ansichten</h3>\n            <p>\n              Dauerhafte Seitenleisten-Ansichten, gespeichert als\n              <code>.solomd/views/*.yml</code> — filtern nach Typ, Status, Datum\n              oder Regex, und sie bleiben über Neustarts hinweg erhalten.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Posteingang-Ablauf</h3>\n            <p>\n              <code>⌘E</code> markiert die aktuelle Notiz als abgelegt und\n              springt automatisch zur nächsten — eine echte Inbox-Zero-Schleife\n              zum Sichten erfasster Notizen.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>tldraw-Whiteboards</h3>\n            <p>\n              Markdown-gestützte Boards über einen\n              <code>```tldraw</code>-Zaun — dauerhaft in der <code>.md</code>\n              der Notiz und kompatibel mit Tolarias Board-Format auf der\n              Festplatte.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Designsystem-UI + vereinheitlichte Titelleiste</h3>\n            <p>\n              Eine warm-neutrale Flächenpalette mit orangem Akzent\n              <code>#ff9f40</code>, neu gebaut auf einer richtigen\n              Vue-Komponentenbibliothek, und eine vereinheitlichte\n              macOS-Titelleiste, die die Ampelknöpfe in die Werkzeugleiste\n              einbettet.\n            </p>\n          </div>\n        </div>",
    "<h2>Fünf Säulen</h2>\n        <p>\n          Jede ist im Kern, in den Einstellungen umschaltbar. Vollständig kompatibel\n          mit Ihren bestehenden Notizen — keine DB-Migration, kein neues Dateiformat,\n          kein erzwungenes Cloud-Konto.\n        </p>\n        <div class=\"pillars\">\n          <div class=\"pillar\">\n            <h3>1 · Internes Agent-Panel</h3>\n            <p>\n              Rechtsseitiges erstklassiges Panel, gleichrangig mit Outline / Backlinks /\n              Tags / History. Gestreamtes chat-with-vault über prozessintere MCP-Schnittstelle\n              und bestehenden 14-Provider-AI-Stack. <code>[[wikilink]]</code>-Zitate\n              lösen sich zu echten Notizsprüngen auf; jede Tool-Call-Karte erweitert sich\n              im Konversationsfluss — Sie sehen, was gelesen, was geschrieben wurde.\n              Antwort zu lang? <strong>Einfügen</strong> und <strong>Kopieren</strong>\n              Schaltflächen lassen den ganzen Absatz in den aktuellen Editor fallen\n              — ersetzt Auswahl wenn vorhanden, fügt sonst an Cursor-Position ein.\n              Lauf-Verlauf bleibt als reines Markdown unter\n              <code>.solomd/agent-runs/</code> erhalten, grep-bar, git-trackbar.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>2 · Agent-Recipe / geplante Ausführung</h3>\n            <p>\n              Deklarative Agent-Aufgaben, YAML-Dateien unter\n              <code>&lt;workspace&gt;/.solomd/agents/*.yml</code>.\n              Trigger: <code>schedule</code> (cron), <code>on-save</code>,\n              <code>on-commit</code>, <code>on-tag-add</code>, manuell.\n              <strong>Sicherheitsleitplanken nicht verhandelbar</strong>: jeder Lauf\n              startet auf einem eigenen AutoGit-Branch\n              <code>agent/&lt;recipe&gt;/&lt;run-id&gt;</code>, alle Schreibaktionen\n              landen nur auf dem Branch, gehen durch accept / reject UI vor Merge in main;\n              pro Lauf <code>write-cap</code> (Standard 5, hartes Maximum 50)\n              verhindert ausser Kontrolle geratene Schleifen; Reject hard-deletet den\n              Branch, dieser Lauf ist im git-Verlauf vollständig unsichtbar. Liefert\n              <strong>11 Recipe-Vorlagen</strong> mit (Wochenrückblick, Log-Aufräumung,\n              TODO-Extraktion, Übersetzung, Zitatsbereinigung, CJK-Korrektur, …) ——\n              installieren, prompt bearbeiten, ausführen.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>3 · Agent-Trace-Ansicht</h3>\n            <p>\n              Jeder Lauf (egal ob Panel-Konversation oder Recipe) generiert\n              schrittweise <code>trace.jsonl</code>:\n              <code>prompt</code> / <code>model_call</code> /\n              <code>tool_call</code> / <code>tool_result</code> /\n              <code>git_commit</code> / <code>done</code>.\n              Schrittkarten klappen auf, um args, Ergebnisse, Token-Zählungen,\n              Kostenschätzungen, AutoGit-Branch-Referenzen anzuzeigen.\n              <strong>Replay-from-step</strong> Schaltfläche spult Lauf zu Schritt N zurück,\n              ändert Eingabe und führt von dort erneut aus — das ist der Eingang\n              zu self-correcting Recipe. Neues MCP-Tool\n              <code>read_agent_trace(run_id)</code> stellt Trace anderen Agents zur Verfügung.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>4 · Multi-Vault MCP-Federation</h3>\n            <p>\n              <code>solomd-mcp --workspace path1 --workspace path2 --workspace path3</code>\n              —— eine MCP-Sitzung, mehrere Vaults. Tool-Signaturen erhalten optionalen\n              <code>workspace</code>-Parameter, Standard = erster übergebener\n              (vollständig back-compat mit single-vault MCP-Clients). AutoGit-Branches\n              nach Workspace getrennt. <strong>Einstellungen → Integrationen</strong>\n              hat MCP-Profil-UI: mehrere Vaults benannt bündeln, ein-Klick\n              Claude-Desktop-Konfigurations-Snippet kopieren.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>5 · Ollama erstklassig</h3>\n            <p>\n              Wir <strong>bündeln keine</strong> lokale LLM-Runtime selbst —\n              Ollama macht das schon gut. v4.0 hat die Integration nur glatter geschliffen:\n              <code>localhost:11434</code> Auto-Erkennung (Einstellungen → KI hat\n              grünes Status-LED), Ein-Klick-Installations-Anleitung wenn nicht installiert,\n              eingebaute 3-Modell-Presets (<code>rewrite</code> → qwen2.5:7b ·\n              <code>quick</code> → qwen2.5:1.5b ·\n              <code>cjk</code> → qwen2.5:14b), Inline-Empfehlung pull bei leerer Modellliste.\n              Recipes können <code>provider: local</code> (Ollama-Alias) angeben für\n              Cloud-kostenfreie Automatisierungsschleifen.\n              <em>Ihre Notizen verlassen die Maschine nie</em> — über BYOK Ollama\n              war das immer wahr, v4.0 macht es zu einem entdeckbaren Eingang.\n            </p>\n          </div>\n        </div>",
    "<h2>🛡️ Sicherheitsleitplanken (was niemand sonst macht)</h2>\n        <ul>\n          <li>\n            <strong>AutoGit-Branch-Sandbox.</strong> Jeder Recipe-Lauf startet auf\n            einem eigenen Branch. Bevor Sie Akzeptieren klicken, bewegt sich\n            <code>main</code> nicht. Reject Läufe <em>hinterlassen nichts</em> ——\n            Branch gelöscht, Dateibaum zurückgespult.\n          </li>\n          <li>\n            <strong>Pro-Lauf-Schreibobergrenze.</strong> Modell will 50 Dateien schreiben\n            wenn cap 5 ist, ab 6. Tool-Aufruf wird abgelehnt. Kein \"halb-fertiger\" Zustand,\n            keine unbeabsichtigten Massenänderungen.\n          </li>\n          <li>\n            <strong>Verweigert Start bei dirty Workspace.</strong> Sie haben uncommittete\n            Änderungen, der Recipe-Trigger feuert, es wird mit Fehler beendet,\n            Ihre WIP wird nicht in Agent-Commits gespült.\n          </li>\n          <li>\n            <strong>Pfad-Traversal-Härtung.</strong> Prozessinterne Tool-Schnittstelle\n            und alle Tauri-Befehle, die benutzerdefinierte <code>run_id</code> /\n            <code>path</code> akzeptieren, lehnen jetzt vorab <code>..</code>-Segmente\n            und absolute Pfade ab. Agent kann auf Code-Ebene nicht außerhalb des Workspaces schreiben.\n          </li>\n          <li>\n            <strong>Wiederholbarer Trace.</strong> Jeder Schritt landet zeilenweise als JSON\n            auf der Festplatte. Panel-Verhalten verdächtig? Trace folgen, schlechten Schritt\n            lokalisieren, Eingabe ändern, von Schritt N–1 wiedergeben.\n          </li>\n        </ul>",
    "<h2>Qualitätsbalken</h2>\n        <ul>\n          <li>\n            <strong>Erststart-Wizard.</strong> Neue Benutzer sehen das Agent-Panel\n            innerhalb von 60 Sekunden — leitet Sie an, BYOK-Schlüssel einzutragen oder\n            Ollama zu installieren. Später aus Hilfe wieder öffenbar.\n          </li>\n          <li>\n            <strong>Recipe-Kochbuch (11 Starter-Vorlagen).</strong>\n            Einstellungen → Recipes → Kochbuch durchsuchen. Wochenrückblick, Tagesbericht,\n            TODO-Extraktion, Übersetzungsdurchgang, Zitatsbereinigung, CJK-Korrektur-Agent,\n            Link-Verfall-Detektor, Frontmatter-Normalisierer, Outline zu Blog,\n            Refactor-Durchgang, wöchentliche Tag-Triage. Installieren, prompt bearbeiten, ausführen.\n          </li>\n          <li>\n            <strong>Lokale REST-API</strong> (lauscht nur auf localhost,\n            Token-Authentifizierung). Gleiche Schnittstelle wie MCP, für Clients,\n            die noch kein MCP sprechen — Alfred / Raycast / n8n / Ihre eigenen Skripte.\n          </li>\n          <li>\n            <strong>BYOK-Kostenmesser.</strong> Pro Provider akkumulierte verbrauchte Tokens,\n            opt-in. Einstellungen → Integrationen.\n          </li>\n          <li>\n            <strong>Lokalisierung.</strong> 9 UI-Sprachen vollständige Abdeckung\n            (en/zh/ja/ko/de/fr/es/pt/it). Diese Release fügte 5 europäische Sprachen\n            hinzu — Deutsch, Französisch, Spanisch, Portugiesisch, Italienisch — alle\n            mit derselben Wörterbuch-Schlüsselparität wie en/zh.\n          </li>\n        </ul>",
    "<h2>UX-Polish, der ab dem ersten Tag spürbar ist</h2>\n        <ul>\n          <li>\n            <strong>IME-Wächter überall.</strong> Pinyin-Chinesisch tippen,\n            Japanisch kana-Modus, Koreanische Hangul — Enter zum Bestätigen\n            der Kandidatenwörter löst nicht mehr versehentlich Konversation senden /\n            Datei-Tree umbenennen / Befehlspaletten-Ausführung / Suchöffnung aus.\n            Einmaliger Fix für <strong>7 Eingabepanels</strong>.\n          </li>\n          <li>\n            <strong>Insert / Copy-Schaltflächen für Assistant-Antworten.</strong>\n            Zwei Schaltflächen unter jeder fertigen Antwort. Insert ist editor-selektion-aware\n            (mit Auswahl ersetzt), ohne Auswahl an Cursor-Position eingefügt.\n            Copy ist normales Clipboard.\n          </li>\n          <li>\n            <strong>macOS Start-UX.</strong> Start-Aktivierungs-Timing repariert\n            —— SoloMD-Kaltstart kommt wirklich in den Vordergrund, versteckt sich nicht\n            mehr hinter Finder. Fenster-Position-Wiederherstellung landet immer im\n            aktuellen Display-Workspace; bei Wiederherstellung von schlechtem Speicher\n            nach Trennung des Sekundärbildschirms wird automatisch neu zentriert,\n            statt außerhalb des Bildschirms zu öffnen.\n          </li>\n          <li>\n            <strong>\"Generierung...\" stuck ohne Fehler.</strong> Repariert.\n            Provider-Konfigurations-Fehler (z. B. Ollama mit nicht-gepulltem Modell)\n            ließ Panel hängen. Jetzt sehen Sie eine rote Fehlerleiste mit der tatsächlichen\n            Backend-Antwort, die Sende-Schaltfläche kommt auch zurück.\n          </li>\n        </ul>",
    "<h2>Was v4.0 ausdrücklich nicht macht (und warum)</h2>\n        <p>Nein zu sagen ist auch Teil des Produkts. Diese wurden ernsthaft erwogen und ausdrücklich nicht gemacht:</p>\n        <ul>\n          <li>\n            <strong>Eigene lokale LLM-Runtime mitbringen.</strong> Ollama macht es schon gut;\n            das Rad neu erfinden verletzt Prinzip \"weniger Code schreiben, der dauerhaft gepflegt werden muss\".\n            BYOK-Provider bleibt der Pfad.\n          </li>\n          <li>\n            <strong>Online-Recipe-Marktplatz.</strong> Server-Betrieb + Inhalts-Moderation = Abweichung von der Hauptlinie.\n            Kochbücher werden direkt in Releases gepackt, mit dem Tool zusammen aktualisiert.\n          </li>\n          <li>\n            <strong>Multi-User / Team-Agent.</strong> Verletzt \"ein Fenster, ein Schreiber\".\n            Dieses Produkt ist für einzelne Autoren; Kollaboration gehört zu einem anderen Produkt.\n          </li>\n          <li>\n            <strong>Copilot-Stil Geistertext-Vervollständigung.</strong> Anderes Brand-Positioning.\n            Geistertext verwässert die Stimme des Schreibers; unsere Agents arbeiten in Vault-Einheiten,\n            Schreibaktionen sind batched + prüfbar + branch-basiert.\n          </li>\n        </ul>",
    "<h2>Upgrade-Hinweise</h2>\n        <ul>\n          <li>\n            <strong>Keine Dateiformat-Änderungen.</strong> Bestehende <code>.md</code>,\n            AutoGit-Verlauf, Sync-Konfiguration, BYOK-Schlüssel alle wie sie sind erhalten.\n          </li>\n          <li>\n            <strong>Agent-Panel beim ersten Start automatisch an.</strong> v3.6.x-Benutzer\n            haben aufgrund des v4-beta-Zeitraum-Gerüst-Defaults möglicherweise versteckte\n            <code>showAgentPanel: false</code>; einmalige Migration kippt es auf true,\n            damit Sie die Hauptfunktion tatsächlich sehen. Wenn Sie sie nicht wollen, können Sie\n            <code>⌘⇧P → View: Toggle Agent Panel</code> ausschalten.\n          </li>\n          <li>\n            <strong>Einstellungs-Panel hat zwei neue Tabs <em>Recipes</em> und <em>Kostenmesser</em></strong>,\n            unter <em>Integrationen</em>. Bestehende Einstellungspositionen unverändert.\n          </li>\n          <li>\n            <strong>MCP-Server (<code>solomd-mcp</code>) erhielt neuen\n            <code>--workspace</code> Parameter</strong> (wiederholbar).\n            Bestehende single-workspace MCP-Clients funktionieren weiterhin;\n            Federation-Verhalten ist opt-in.\n          </li>\n        </ul>",
    "<h2>🔮 Was kommt als Nächstes</h2>\n        <p>\n          5 Hauptsäulen + Qualitätsbalken sind der Hauptinhalt dieses Mal. <em>Offene\n          Richtungen für v4.x und danach</em> sind alle in der\n          <a href=\"https://github.com/zhitongblog/solomd/blob/main/docs/roadmap.md\">roadmap</a>:\n          sandboxierte Skript-API, CLI v2 (rewrite / commit / semantische Suche /\n          Recipe im Terminal triggern), und die immer noch verzögerte\n          <em>\"Sollte SoloMD ein kommerzielles Produkt werden?\"</em>-Frage\n          (kostenpflichtige Sync — alte Frage aus der v3.0-Ära, immer noch unbeantwortet,\n          bis entschieden wird, wird in diesem Bereich keine Engineering gemacht).\n        </p>",
  ],
  thanks: "Danke an alle, die während der Stille-Periode Issues eingereicht / PRs gesendet /\n        v4-beta-Builds mit echten Vaults gefahren haben. v4.0 konnte ausgeliefert werden,\n        weil Dogfood die Bugs aufgedeckt hat, die Integrationstests übersehen haben.\n        Frühere Versionen: <a href=\"/blog/\">Blog ansehen (en) →</a>",
};

export default data;
